<script setup>
import { onMounted,reactive,ref } from 'vue';import { ElMessage } from 'element-plus';import { createSyncTask,listSyncTasks,listSystems,runSyncTask } from '../../api/external';import { formatDate,tagType } from '../../utils/enums';import PageHeader from '../../components/PageHeader.vue';import AppPagination from '../../components/AppPagination.vue';import { messageOf } from '../../utils/request'
const systems=ref([]);const state=reactive({list:[],total:0,pageNum:1,pageSize:10,status:'',loading:false});const open=ref(false);const form=reactive({caseId:null,systemCode:'CPC',syncType:'PUSH',simulateFailure:false});const load=async()=>{const r=await listSyncTasks({pageNum:state.pageNum,pageSize:state.pageSize,status:state.status||undefined});state.list=r.data.list;state.total=r.data.total};const create=async()=>{try{await createSyncTask(form);open.value=false;ElMessage.success('同步任务已创建');load()}catch(e){ElMessage.error(messageOf(e))}};const run=async(row,retry=false)=>{try{await runSyncTask(row.id,retry);ElMessage.success('任务状态已更新');load()}catch(e){ElMessage.error(messageOf(e))}};onMounted(async()=>{systems.value=(await listSystems({pageSize:100})).data.list;load()})
</script>
<template><div class="page"><PageHeader title="外部系统同步" description="使用 Mock Adapter 演示 CPC、商标和缴费系统同步"><el-button type="primary" @click="open=true">创建同步任务</el-button></PageHeader><div class="toolbar"><el-select v-model="state.status" placeholder="同步状态" clearable @change="load"><el-option v-for="v in ['PENDING','PROCESSING','SUCCESS','FAILED']" :key="v" :value="v"/></el-select></div><div class="table-wrap"><el-table :data="state.list"><el-table-column prop="id" label="任务 ID" width="90"/><el-table-column prop="externalSystemId" label="系统 ID" width="90"/><el-table-column prop="businessId" label="案件 ID"/><el-table-column prop="syncType" label="同步类型"/><el-table-column label="状态"><template #default="{row}"><el-tag :type="tagType(row.status)">{{row.status}}</el-tag></template></el-table-column><el-table-column label="完成时间" width="160"><template #default="{row}">{{formatDate(row.finishTime)}}</template></el-table-column><el-table-column width="110"><template #default="{row}"><el-button v-if="row.status==='PENDING'" link @click="run(row)">执行</el-button><el-button v-if="row.status==='FAILED'" link type="warning" @click="run(row,true)">重试</el-button></template></el-table-column></el-table></div><AppPagination v-model:page="state.pageNum" v-model:size="state.pageSize" :total="state.total" @change="load"/><el-dialog v-model="open" title="创建外部同步任务" width="min(520px,94vw)"><el-form label-position="top"><el-form-item label="案件 ID"><el-input-number v-model="form.caseId" :min="1"/></el-form-item><el-form-item label="外部系统"><el-select v-model="form.systemCode"><el-option v-for="s in systems" :key="s.systemCode" :label="s.systemName" :value="s.systemCode"/></el-select></el-form-item><el-form-item label="同步类型"><el-select v-model="form.syncType"><el-option label="推送案件" value="PUSH"/><el-option label="拉取文档元数据" value="PULL"/><el-option label="查询状态" value="STATUS_QUERY"/></el-select></el-form-item><el-form-item><el-checkbox v-model="form.simulateFailure">模拟失败（用于演示重试）</el-checkbox></el-form-item></el-form><template #footer><el-button @click="open=false">取消</el-button><el-button type="primary" @click="create">创建</el-button></template></el-dialog></div></template>
